/**
 * @description Tests for the IH_SampleResponseHandler template: parsing, nothing done without a target field, and the
 * reference copied to the sent record when one is set.
 */
@IsTest
private class IH_SampleResponseHandlerTest {

    private static final String USER_DOMAIN = '@ihsampleresponse.example.com';

    @TestSetup
    static void setup() {
        List<Profile> profiles = [SELECT Id FROM Profile WHERE Name = 'Standard User' WITH SYSTEM_MODE LIMIT 1];
        Id profileId = profiles.isEmpty() ? UserInfo.getProfileId() : profiles[0].Id;
        String unique = EncodingUtil.convertToHex(Crypto.generateAesKey(128)).left(10);
        User tester = new User(LastName = 'IH Sample Tester', Alias = unique.left(8), Email = unique + '@example.com',
            Username = unique + '.response' + USER_DOMAIN, ProfileId = profileId, EmailEncodingKey = 'UTF-8',
            LanguageLocaleKey = 'en_US', LocaleSidKey = 'en_US', TimeZoneSidKey = 'America/Chicago');
        System.runAs(new User(Id = UserInfo.getUserId())) {
            insert tester;
        }
    }

    private static User tester() {
        String pattern = '%.response' + USER_DOMAIN;
        return [SELECT Id FROM User WHERE Username LIKE :pattern WITH SYSTEM_MODE LIMIT 1];
    }

    @IsTest
    static void parsesOnlyJsonObjects() {
        System.runAs(tester()) {
            Assert.isNull(IH_SampleResponseHandler.parse(null), 'no body');
            IntegrationHub.ResponseContext ctx = new IntegrationHub.ResponseContext();
            ctx.relatedRecordId = UserInfo.getUserId();
            ctx.body = '{"status":"SUCCESS","reference":"R-2","data":{"voucher":"V-9"}}';
            ctx.data = new Map<String, Object>{ 'voucher' => 'V-9' };
            new IH_SampleResponseHandler().handle(ctx);
            Assert.areEqual('Reference R-2, data keys: voucher', ctx.result, 'the handler sets a result line from the data');
            Assert.isNull(IH_SampleResponseHandler.parse('not json'), 'not JSON');
            Assert.isNull(IH_SampleResponseHandler.parse('[1,2]'), 'not an object');
            Assert.areEqual('R-1', IH_SampleResponseHandler.parse('{"reference":"R-1"}').get('reference'), 'an object is read');
            new IH_SampleResponseHandler().handle(null);
        }
    }

    @IsTest
    static void copiesTheReferenceWhenATargetFieldIsSet() {
        Case c;
        System.runAs(new User(Id = UserInfo.getUserId())) {
            try {
                c = new Case(Subject = 'Sample response test');
                insert c;
            } catch (DmlException e) {
                c = null;
            }
        }
        System.runAs(tester()) {
            if (c == null) {
                Assert.isNull(c, 'the org does not allow a test Case; nothing else to check');
                return;
            }
            IntegrationHub.ResponseContext ctx = new IntegrationHub.ResponseContext();
            ctx.relatedRecordId = c.Id;
            ctx.body = '{"status":"SUCCESS","reference":"EXT-42"}';
            new IH_SampleResponseHandler().handle(ctx);
            IH_SampleResponseHandler.targetField = 'Description';
            Test.startTest();
            new IH_SampleResponseHandler().handle(ctx);
            Test.stopTest();
            Case saved = [SELECT Description FROM Case WHERE Id = :c.Id WITH SYSTEM_MODE LIMIT 1];
            Assert.areEqual('EXT-42', saved.Description, 'the reference is copied to the target field');
        }
    }
}
